import {Game,BOSS,RESONATOR,MOTIF} from './game.js';
const $=id=>document.getElementById(id),canvas=$('scene'),ctx=canvas.getContext('2d');
const game=new Game(),bg=new Image();bg.src='assets/hall.png';
const keys=new Set(),joy={x:0,y:0};let started=false,paused=false,muted=false,W=0,H=0,last=0,beat=-1,captionUntil=0,flash=0,shake=0,attackHeld=false,lastRangeHint=-10;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let audio,master;
function initAudio(){try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=.24;master.connect(audio.destination);}audio.resume().catch(()=>{});}catch{muted=true;$('sound').textContent='Звук недоступний';}}
function tone(freq,duration=.3,volume=.2,type='sine',delay=0){if(!audio||muted||paused||audio.state!=='running')return;const t=audio.currentTime+delay,osc=audio.createOscillator(),gain=audio.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,t);gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(volume,t+.012);gain.gain.exponentialRampToValueAtTime(.0001,t+duration);osc.connect(gain);gain.connect(master);osc.start(t);osc.stop(t+duration+.03);osc.onended=()=>{osc.disconnect();gain.disconnect();};}
function say(text,seconds=4){$('caption').textContent=text;captionUntil=game.time+seconds;}
function resize(){const b=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);W=b.width;H=b.height;canvas.width=Math.round(W*d);canvas.height=Math.round(H*d);ctx.setTransform(d,0,0,d,0,0);}
new ResizeObserver(resize).observe(canvas);
function projection(x,y){const rx=Math.min(W*.43,H*.72),ry=Math.min(H*.24,W*.24);return {x:W*.5+x*rx,y:H*.56+y*ry};}
function ellipse(x,y,r,color,width=2){const p=projection(x,y),a=projection(x+r,y),b=projection(x,y+r);ctx.beginPath();ctx.ellipse(p.x,p.y,Math.abs(a.x-p.x),Math.abs(b.y-p.y),0,0,Math.PI*2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
function orb(x,y,r,color){const p=projection(x,y);ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fillStyle=color;ctx.shadowColor=color;ctx.shadowBlur=12;ctx.fill();ctx.shadowBlur=0;}
function line(a,b,color,width=2){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
function face(x,y,scale,active,index){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.shadowBlur=active?18:0;ctx.shadowColor='#dfbb82';ctx.fillStyle=active?'#e3d4b7':'#787c78';ctx.strokeStyle='#302f29';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-16,-27);ctx.quadraticCurveTo(0,-39,16,-27);ctx.lineTo(13,4);ctx.lineTo(0,17);ctx.lineTo(-13,4);ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.strokeStyle=active?'#6d4a1f':'#485552';ctx.lineWidth=3;line({x:-10,y:-13},{x:-3,y:-14},ctx.strokeStyle,3);line({x:3,y:-14},{x:10,y:-13},ctx.strokeStyle,3);line({x:0,y:-10},{x:0,y:0},'#a7987c',1);line({x:-5,y:5},{x:5,y:5},active?'#30271c':'#555b57',2);for(let i=0;i<index;i++)line({x:(i-index/2)*5+2,y:25},{x:(i-index/2)*5+2,y:33},active?'#dcb576':'#8a958e',2);ctx.restore();}
function android(p){const pos=projection(p.x,p.y),s=Math.max(12,Math.min(W,H)*.032),walk=Math.hypot(joy.x,joy.y)>0||keys.size>0;const cycle=walk?Math.sin(game.time*13):0;ctx.save();ctx.translate(pos.x,pos.y);if(p.inv>0&&Math.floor(game.time*18)%2===0)ctx.globalAlpha=.45;ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(0,4,s*.65,s*.2,0,0,7);ctx.fill();line({x:-s*.16,y:-s*.55},{x:-s*.25+cycle*s*.12,y:s*.05},'#c9c1a4',s*.16);line({x:s*.16,y:-s*.55},{x:s*.25-cycle*s*.12,y:s*.05},'#c9c1a4',s*.16);ctx.beginPath();ctx.moveTo(-s*.36,-s*1.5);ctx.quadraticCurveTo(-s*.7,-s*.5,-s*.54+cycle*s*.08,0);ctx.lineTo(s*.52-cycle*s*.07,-s*.17);ctx.lineTo(s*.34,-s*1.5);ctx.closePath();ctx.fillStyle='#204a52';ctx.fill();ctx.strokeStyle='#8eb6af';ctx.lineWidth=1;ctx.stroke();line({x:0,y:-s*1.3},{x:0,y:-s*.3},'#ac945d',1);ctx.fillStyle='#eee6d3';ctx.beginPath();ctx.ellipse(0,-s*1.72,s*.25,s*.32,0,0,7);ctx.fill();line({x:s*.38,y:-s*1.1},{x:s*.78,y:-s*.88-cycle*s*.08},'#ded6be',s*.1);const strike=p.attack>.15?s*.4:0;line({x:s*.75,y:-s*.45},{x:s*.95+strike,y:-s*1.8},'#b9cfc7',2);line({x:s*.95+strike,y:-s*1.8},{x:s*1.04+strike,y:-s*2.08},'#e4e8d3',2);line({x:s*.95+strike,y:-s*1.8},{x:s*.83+strike,y:-s*2.06},'#e4e8d3',2);if(p.parryWindow>0){ctx.beginPath();ctx.arc(0,-s*.9,s*1.3,0,7);ctx.strokeStyle='#c9f2ee';ctx.lineWidth=3;ctx.stroke();}if(p.attack>.1){ctx.beginPath();ctx.arc(0,-s,2.3*s,-1.8,.4);ctx.strokeStyle='#b9ebe5';ctx.lineWidth=3;ctx.stroke();}ctx.restore();}
function render(){if(!W||!H)return;ctx.clearRect(0,0,W,H);ctx.save();if(shake>0&&!reduced)ctx.translate(Math.sin(game.time*81)*shake*4,Math.cos(game.time*67)*shake*2);
 if(bg.complete&&bg.naturalWidth){const scale=Math.max(W/bg.width,H/bg.height);ctx.drawImage(bg,(W-bg.width*scale)/2,(H-bg.height*scale)/2,bg.width*scale,bg.height*scale);}else{ctx.fillStyle='#293338';ctx.fillRect(0,0,W,H);}
 ctx.fillStyle=started?'#0b191c55':'#0c1c2220';ctx.fillRect(0,0,W,H);
 if(started){const c=projection(0,0),a=projection(1,0),b=projection(0,1);ctx.beginPath();ctx.ellipse(c.x,c.y,a.x-c.x,b.y-c.y,0,0,7);ctx.fillStyle='#15292c75';ctx.fill();ellipse(0,0,.97,'#c6b18370',1);ellipse(0,0,.71,'#bdb39938',1);ellipse(0,0,.4,'#bdb39935',1);
 const rp=projection(RESONATOR.x,RESONATOR.y);orb(RESONATOR.x,RESONATOR.y,4,'#94dad5');ellipse(RESONATOR.x,RESONATOR.y,.09,'#abd2c8aa',2);line({x:rp.x,y:rp.y-6},{x:rp.x,y:rp.y-26},'#bfaa77',2);ctx.fillStyle='#e3d7ba';ctx.font='10px Arial';ctx.textAlign='center';if(game.mode==='explore')ctx.fillText('Ⅰ Ⅲ Ⅱ',rp.x,rp.y-38);
 const boss=projection(BOSS.x,BOSS.y),scale=Math.max(.7,Math.min(W,H)/530);for(let i=0;i<3;i++)face(boss.x+(i-1)*48*scale,boss.y-35*scale,scale,game.mode==='battle'&&i+1===game.boss.phase,i+1);
 if(game.pending){const t=Math.max(0,game.pending.at-game.time),pattern=game.pending.pattern;if(pattern==='beam'){const a=game.pending.angle;line(projection(BOSS.x,BOSS.y),projection(BOSS.x+Math.cos(a)*2,BOSS.y+Math.sin(a)*2),'#efb96a88',2);}else ellipse(BOSS.x,BOSS.y,.11+(1.1-t)*.18,'#e9c18d88',2);}
 for(const r of game.rings)ellipse(BOSS.x,BOSS.y,r.r,'#f6c684',Math.max(3,W*.003));
 if(game.beam){const a=game.beam.angle;line(projection(BOSS.x,BOSS.y),projection(BOSS.x+Math.cos(a)*2,BOSS.y+Math.sin(a)*2),'#f9d8a0',Math.max(9,W*.01));}
 for(const bullet of game.bullets){const radius=Math.max(3,Math.min(W,H)*.009);orb(bullet.x,bullet.y,radius,bullet.reflectable?'#ffe3a4':'#ba8354');if(bullet.reflectable){const pos=projection(bullet.x,bullet.y);ctx.strokeStyle='#fff0c0';ctx.lineWidth=1;ctx.strokeRect(pos.x-radius-2,pos.y-radius-2,2*radius+4,2*radius+4);}}
 android(game.player);
 for(const e of game.effects){if(e.kind==='pulse')ellipse(e.x,e.y,(.65-e.life)*2.4,'#b8f7f0',3);else ellipse(e.x,e.y,(.25-e.life)*1.3,'#f0eee0',2);}
 if(game.ending==='keep'){ellipse(BOSS.x,BOSS.y,.5+Math.sin(game.time)*.05,'#b7e0d088',2);orb(BOSS.x,BOSS.y,8,'#9bd9cc');}
 const particles=reduced?8:30;for(let i=0;i<particles;i++){const x=(i*79.13+Math.sin(game.time*.35+i)*16)%W,y=(i*137.7-game.time*(5+i%4)+H*100)%H;ctx.fillStyle=i%3?'#e4d9bc45':'#bcdfd470';ctx.fillRect(x,y,1.5,1.5);}
 }
 if(flash>0){ctx.fillStyle=`rgba(177,59,38,${flash*.2})`;ctx.fillRect(0,0,W,H);}ctx.restore();}
function ui(){const p=game.player;$('health').innerHTML=Array.from({length:5},(_,i)=>`<i class="${i>=p.hp?'empty':''}"></i>`).join('');$('health').setAttribute('aria-label',`Міцність: ${p.hp} з 5`);$('res-value').textContent=`${Math.floor(p.res)} / 100`;$('res-bar').style.width=p.res+'%';$('boss-bar').style.width=game.boss.hp/game.boss.max*100+'%';$('boss-hud').hidden=game.mode!=='battle';$('phase').textContent=['','Ⅰ БАС','Ⅱ ТЕНОР','Ⅲ ДИСКАНТ'][game.boss.phase];$('pulse').disabled=game.mode!=='battle'||p.res<40;$('attack').disabled=game.mode!=='battle';$('parry').disabled=game.mode!=='battle';$('interact').disabled=!game.near||game.mode!=='explore';$('dodge').disabled=p.dodge>0||!['battle','explore'].includes(game.mode);$('chapter').textContent=game.mode==='explore'?'01 / ЗАЛ ВІДЛУНЬ':game.mode==='battle'?'02 / ТРИ ОБЛИЧЧЯ':'03 / ТИША';$('objective').textContent=game.mode==='explore'?'Знайди резонатор праворуч':game.mode==='battle'?'Вивчи голос. Відповідай камертоном.':'Що залишиться після тебе?';$('hint').textContent=game.mode==='explore'?(game.near?'E / Дія — налаштувати резонатор':'Рухайся до блакитного резонатора праворуч'):game.mode==='battle'&&game.player.dodge>.46?'УХИЛЕННЯ':game.mode==='battle'&&game.player.parryWindow>0?'ВІДБИТТЯ':'';if(game.time>captionUntil)$('caption').textContent='';}
function panel(label,title,text,actions){$('panel-label').textContent=label;$('panel-title').textContent=title;$('panel-text').textContent=text;$('panel-actions').replaceChildren();for(const [name,fn] of actions){const button=document.createElement('button');button.textContent=name;button.className='primary';button.onclick=fn;$('panel-actions').append(button);}$('overlay').hidden=false;$('panel-actions').querySelector('button')?.focus();}
function hideOverlay(){$('overlay').hidden=true;keys.clear();joy.x=joy.y=0;attackHeld=false;}
function events(){for(const e of game.events.splice(0)){switch(e.type){case 'puzzle':$('puzzle').hidden=false;$('puzzle').querySelector('[data-note]')?.focus();tone(130.81,.5);break;case 'wrong-note':tone(92,.15);$('note-progress').textContent='Спробуй ще раз';break;case 'battle':$('puzzle').hidden=true;say('Провідник: «Три джерела. Одна несправність. Припини сигнал.»',6);tone(130.81,1);break;case 'attack':tone(523.25,.1,.15,'triangle');break;case 'out-of-range':if(game.time-lastRangeHint>3){say('Підійди ближче до облич. Камертон дістає лише зблизька.',2);lastRangeHint=game.time;}break;case 'dodge':tone(220,.1,.08);break;case 'parry':tone(783.99,.15,.1);break;case 'pulse':tone(65.41,1,.5,'triangle');shake=.6;break;case 'reflected':tone(1046.5,.35,.25);say('ВІДБИТО · +14 резонансу',2);break;case 'hurt':flash=1;shake=.8;tone(55,.3,.25,'sawtooth');break;case 'phase':tone(e.phase===2?196:261.63,1,.2);say(e.phase===2?'ДРУГИЙ ГОЛОС · Кільце пройде крізь зал. Ухились.':'ТРЕТІЙ ГОЛОС · Голоси чергуються. Читай попередження.',4);break;case 'telegraph':$('telegraph').textContent={fan:'ВІЯЛО · залишайся між імпульсами',ring:'КІЛЬЦЕ · ухились крізь хвилю',beam:'ПРОМІНЬ · зміни позицію'}[e.pattern];tone({fan:65.41,ring:196,beam:392}[e.pattern],.8,.18);break;case 'pattern':tone(e.pattern==='ring'?98:130.81,.6,.3,'triangle');break;case 'dead':panel('СИГНАЛ ПЕРЕРВАВСЯ','Спробуй почути ще раз.','Кільця проходять крізь відбиття. Ухиляйся кнопкою Space. Бурштиновий імпульс у квадратному контурі можна відбити K.',[['Повернутися до бою',()=>{hideOverlay();game.reset();game.mode='battle';game.nextPattern=2.5;game.player.res=60;beat=-1;}],['Почати з резонатора',restart]]);break;case 'victory':tone(261.63,2,.2);say('Провідник: «Сигнал припинено… Чому він захищав інших?»',8);panel('ПАРТІЮ ОТРИМАНО','Перемога залишає тишу.','Три голоси більше не атакують. У камертоні залишився їхній мотив. Твій наказ ще можна виконати.',[['Зберегти голос',()=>{hideOverlay();game.choose('keep');}],['Виконати наказ: стерти',()=>{hideOverlay();game.choose('silence');}]]);break;case 'ending':const keep=e.choice==='keep';if(keep){tone(130.81,2,.2);tone(196,2,.13);tone(261.63,2,.1);}panel('КІНЕЦЬ ВЕБПРОТОТИПУ',keep?'Хор іще пам’ятає.':'Зал замовк.',keep?'Ти зберіг партію. Уперше відповідь була твоєю, а не наказом.':'Сигнал стерто. Завдання виконане. Чому від цього не стало легше?', [['Зіграти ще раз',restart]]);try{localStorage.setItem('choir-last-play',JSON.stringify({ending:e.choice,hits:game.hits,reflected:game.reflected}));}catch{}break;}}}
function restart(){hideOverlay();$('intro').hidden=true;$('puzzle').hidden=true;paused=false;game.reset();beat=-1;$('pause').textContent='Ⅱ';say('Провідник: «Носію, прямуй до джерела. Резонатор праворуч.»',6);initAudio();}
$('start').onclick=()=>{started=true;$('hud').hidden=false;$('controls').hidden=false;restart();};
function doAction(name){if(!started||paused||!$('overlay').hidden||!$('puzzle').hidden)return;game[name]();events();ui();}
for(const name of ['attack','dodge','parry','pulse','interact'])$(name).onclick=()=>doAction(name);
function setPause(value){if(!started||!['explore','battle'].includes(game.mode))return;paused=value;keys.clear();joy.x=joy.y=0;attackHeld=false;$('pause').textContent=paused?'▶':'Ⅱ';if(paused){audio?.suspend().catch(()=>{});panel('ПАУЗА','Зал зачекає.','Рух: WASD або стік. J — удар поблизу облич. Space — ухилення крізь кільце. K — відбиття позначених імпульсів. Q — хвиля резонансу за 40 одиниць.',[['Продовжити',()=>{hideOverlay();setPause(false);}],['Почати спочатку',restart]]);}else{hideOverlay();initAudio();}}
$('pause').onclick=()=>setPause(!paused);$('sound').onclick=()=>{muted=!muted;if(!muted)initAudio();if(master)master.gain.value=muted?0:.24;$('sound').textContent=muted?'Звук: вимкнено':'Звук: увімкнено';};
const symbols=['','Ⅰ','Ⅱ','Ⅲ'];document.querySelectorAll('[data-note]').forEach(button=>button.onclick=()=>{const n=Number(button.dataset.note);tone([0,130.81,196,261.63][n],.6,.3);game.note(n);$('note-progress').textContent=game.notes.map(v=>symbols[v]).concat(Array(3-game.notes.length).fill('_')).join('   ');events();ui();});
$('listen').onclick=()=>MOTIF.forEach((n,i)=>tone([0,130.81,196,261.63][n],.6,.3,'sine',i*.7));
const actionKeys={KeyJ:'attack',KeyK:'parry',KeyQ:'pulse',KeyE:'interact',Space:'dodge'};
window.addEventListener('keydown',e=>{const modal=!$('overlay').hidden?$('overlay'):!$('puzzle').hidden?$('puzzle'):null;if(e.code==='Tab'&&modal){const buttons=Array.from(modal.querySelectorAll('button')).filter(b=>!b.disabled);const i=buttons.indexOf(document.activeElement),next=e.shiftKey?(i<=0?buttons.length-1:i-1):(i+1)%buttons.length;e.preventDefault();buttons[next]?.focus();return;}if(started&&!paused&&!modal&&['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'){if(!$('puzzle').hidden){$('puzzle').hidden=true;game.mode='explore';game.notes=[];}else setPause(!paused);return;}if(!started||paused||!$('overlay').hidden||!$('puzzle').hidden)return;keys.add(e.code);if(actionKeys[e.code]&&!e.repeat)doAction(actionKeys[e.code]);});window.addEventListener('keyup',e=>keys.delete(e.code));
$('attack').addEventListener('pointerdown',()=>{attackHeld=true;doAction('attack');});$('attack').addEventListener('pointercancel',()=>attackHeld=false);
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){attackHeld=true;doAction('attack');}});window.addEventListener('pointerup',()=>attackHeld=false);
let stickPointer=null;function moveStick(e){const rect=$('stick').getBoundingClientRect(),dx=e.clientX-rect.left-rect.width/2,dy=e.clientY-rect.top-rect.height/2,len=Math.hypot(dx,dy),max=rect.width*.35;joy.x=dx/Math.max(max,len);joy.y=dy/Math.max(max,len);$('stick-knob').style.transform=`translate(${joy.x*max}px,${joy.y*max}px)`;}
$('stick').addEventListener('pointerdown',e=>{stickPointer=e.pointerId;$('stick').setPointerCapture(e.pointerId);moveStick(e);});$('stick').addEventListener('pointermove',e=>{if(stickPointer===e.pointerId)moveStick(e);});function releaseStick(){stickPointer=null;joy.x=joy.y=0;$('stick-knob').style.transform='';}for(const event of ['pointerup','pointercancel','lostpointercapture'])$('stick').addEventListener(event,releaseStick);
window.addEventListener('blur',()=>{releaseStick();keys.clear();attackHeld=false;setPause(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden)setPause(true);});
function input(){return{x:joy.x+(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),y:joy.y+(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)};}
let uiClock=0;function frame(timestamp){const dt=last?Math.min((timestamp-last)/1000,.05):0;last=timestamp;if(started&&!paused){game.step(dt,input());if(attackHeld||keys.has('KeyJ'))doAction('attack');events();if(game.mode==='battle'){const next=Math.floor(game.time/.625);if(next!==beat){beat=next;tone(beat%4===0?65.41:130.81,.5,.12);if(game.boss.phase>=2)tone([196,220,261.63,196][beat%4],.5,.07);if(game.boss.phase===3&&beat%2===0)tone(392,.45,.07);}}flash=Math.max(0,flash-dt*3);shake=Math.max(0,shake-dt*4);uiClock+=dt;if(uiClock>.1){ui();uiClock=0;}}render();requestAnimationFrame(frame);}resize();requestAnimationFrame(frame);
